fn boundShift(x:i64)i64{return 2147483647;}
fn leftRun(a:[*]const i64,k:i64,b:i64,h:i64)struct{o:i64,l:i64}{const m=h+1;var x:i64=1;var t:i64=0;while(x<m and k<a[@intCast(b+h-x)]){t=x;x=boundShift(x);}const y=@min(x,m);return .{.o=h-t,.l=h-y};}
fn rightRun(a:[*]const i64,k:i64,b:i64,n:i64,h:i64)struct{o:i64,l:i64}{var x:i64=1;var last:i64=0;const m=n-h;while(x<m and k>a[@intCast(b+h+x)]){last=x;x=boundShift(x);}const y=@min(x,m);return .{.o=y+h,.l=last+h};}
fn finalOffset(a:[*]const i64,k:i64,b:i64,o0:i64,l0:i64,lt:i64)i64{var o=o0;var l=l0+1;while(l<o){const mid=l+@as(i64,@intCast(@as(u64,@intCast(o-l))>>1));const value=a[@intCast(b+mid)];const cmp: i64=if(k<value)-1 else if(k>value)1 else 0;if(cmp<lt){o=mid;}else{l=mid+1;}}return o;}
export fn galloping_strategy(v:[*]const i64,n:usize)i64{if(n<5 or n>69)return -1;const op=v[0];const count=v[1];const base=v[2];const len=v[3];const key=v[4];if((op!=0 and op!=1) or count<0 or count>64 or n!=5+@as(usize,@intCast(count)) or base<0 or len<0 or base>count or len>count-base or key< -2147483648 or key>2147483647)return -1;const a=v+5;for(0..@intCast(count))|i|{if(a[i]< -2147483648 or a[i]>2147483647)return -1;}if(count==0)return 0;if(len==0 or base>=count)return -1;var i=base;while(i+1<base+len):(i+=1){if(a[@intCast(i)]>a[@intCast(i+1)])return -1;}var pair:struct{o:i64,l:i64}=undefined;if(op==0){pair=if(key>a[@intCast(base)])rightRun(a,key,base,len,0)else leftRun(a,key,base,0);return finalOffset(a,key,base,pair.o,pair.l,1);}pair=if(key<a[@intCast(base)])leftRun(a,key,base,len)else rightRun(a,key,base,len,0);return finalOffset(a,key,base,pair.o,pair.l,0);}
